import hashlib
import os
from typing import List, Dict


# =========================
# 🔐 VALID ALGORITHMS
# =========================
SAFE_ALGORITHMS = {"sha256", "sha512", "blake2b"}


# =========================
# 🔐 HASH SINGLE FILE
# =========================
def hash_file(path: str, algorithm: str = "sha256") -> str:

    if algorithm not in SAFE_ALGORITHMS:
        raise ValueError(f"Use a secure algorithm: {SAFE_ALGORITHMS}")

    if not os.path.exists(path):
        raise FileNotFoundError(f"File not found: {path}")

    if not os.path.isfile(path):
        raise ValueError(f"Not a file: {path}")

    hasher = hashlib.new(algorithm)

    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            hasher.update(chunk)

    return hasher.hexdigest()


# =========================
# 🔐 HASH MULTIPLE FILES
# =========================
def hash_files(paths: List[str], algorithm: str = "sha256") -> Dict[str, str]:

    results = {}

    for path in paths:
        try:
            results[path] = hash_file(path, algorithm)
        except Exception as e:
            results[path] = f"ERROR: {str(e)}"

    return results


# =========================
# 📁 HASH DIRECTORY (DETERMINISTIC)
# =========================
def hash_directory(directory: str, algorithm: str = "sha256") -> Dict[str, str]:

    if not os.path.isdir(directory):
        raise ValueError(f"Not a directory: {directory}")

    results = {}

    for root, _, files in os.walk(directory):
        files.sort()  # ✅ ensure consistent order

        for file in files:
            full_path = os.path.join(root, file)
            results[full_path] = hash_file(full_path, algorithm)

    return results


# =========================
# 🔥 HASH WHOLE DIRECTORY (SINGLE HASH)
# =========================
def hash_directory_combined(directory: str, algorithm: str = "sha256") -> str:
    """
    Create a single hash representing entire directory.
    """

    if not os.path.isdir(directory):
        raise ValueError(f"Not a directory: {directory}")

    hasher = hashlib.new(algorithm)

    for root, _, files in os.walk(directory):
        files.sort()

        for file in files:
            full_path = os.path.join(root, file)

            # include filename in hash (important!)
            hasher.update(full_path.encode())

            with open(full_path, "rb") as f:
                for chunk in iter(lambda: f.read(8192), b""):
                    hasher.update(chunk)

    return hasher.hexdigest()